        return findArtifact(resolution.finalName(), resolution.finalVersion());
    }

    private ArtifactVersion findArtifact(String name, int version) {
        List<ArtifactVersion> candidates = all.get(name);
        if (candidates == null) {
            return null;
        }
        return candidates.stream()
                .filter(a -> a.version() == version && !a.withdrawn())
                .findFirst().orElse(null);
    }

    /**
     * 递归回溯：选出字典序最小的未解析依赖名称，从高到低尝试候选版本；
     * 候选不可用时触发替代，替代结果对整张图唯一。
     */
    private boolean solve(TreeMap<String, ArtifactVersion> chosen) {
        String next = null;
        int lo = Integer.MAX_VALUE;
        int hi = Integer.MIN_VALUE;
        for (ArtifactVersion artifact : chosen.values()) {
            for (DependencyRange dep : artifact.dependencies()) {
                String depName = resolveDepName(dep.name(), chosen);
                if (chosen.containsKey(depName)) {
                    continue;
                }
                if (next == null || depName.compareTo(next) < 0) {
                    next = depName;
                    lo = dep.minimumVersion();
                    hi = dep.maximumVersion();
                } else if (depName.equals(next)) {
                    lo = Math.max(lo, dep.minimumVersion());
                    hi = Math.min(hi, dep.maximumVersion());
                }
            }
        }

        if (next == null) {
            return true;
        }
        if (lo > hi) {
            return false;
        }

        // 若该原名称已在其他路径上完成替代，则其最终坐标必须是唯一候选。
        NodeResolution forced = substitutions.get(next);
        if (forced != null) {
            ArtifactVersion forcedArtifact = findArtifact(forced.finalName(), forced.finalVersion());
            if (forcedArtifact == null
                    || forcedArtifact.version() < lo || forcedArtifact.version() > hi
                    || !satisfiesChosen(forcedArtifact, chosen)) {
                return false;
            }
            chosen.put(forcedArtifact.name(), forcedArtifact);
            if (solve(chosen)) {
                return true;
            }
            chosen.remove(forcedArtifact.name());
            return false;
        }

        List<ArtifactVersion> candidates = all.getOrDefault(next, List.of());
        for (ArtifactVersion candidate : candidates) {
            if (candidate.version() < lo || candidate.version() > hi) {
                continue;
            }
            if (candidate.availableOn(platform)) {
                if (!satisfiesChosen(candidate, chosen)) {
                    continue;
                }
                chosen.put(next, candidate);
                if (solve(chosen)) {
                    return true;
                }
                chosen.remove(next);
                continue;
            }
            // 选中版本撤回/平台不可用：按策略尝试替代。
            ArtifactVersion replaced = trySubstitute(candidate, chosen);
            if (replaced == null) {
                continue;
            }
            if (replaced.version() < lo || replaced.version() > hi
                    || !satisfiesChosen(replaced, chosen)) {
                // 替代后版本约束不相容：同节点可能存在其他版本候选，继续尝试。
                continue;
            }
            chosen.put(replaced.name(), replaced);
            if (solve(chosen)) {
                return true;
            }
            chosen.remove(replaced.name());
        }
        return false;
    }

    /**
     * 依赖名称本身可能是被替代节点的原名：依赖指向原坐标时，应连接到替代后的最终名称。
     * 已确定替代的原名称映射到最终名称；否则原样返回。
     */
    private String resolveDepName(String depName, Map<String, ArtifactVersion> chosen) {
        NodeResolution resolution = substitutions.get(depName);
        if (resolution != null) {
            return resolution.finalName();
        }
        return depName;
    }

    /**
     * 对不可用候选依次尝试命中规则的替代坐标，返回首个可形成可行节点的结果。
     * 每次替代都会重新解析该节点的完整传递依赖（由上层 solve 回溯完成）。
     */
    private ArtifactVersion trySubstitute(ArtifactVersion candidate,
                                          TreeMap<String, ArtifactVersion> chosen) {
        Coordinate original = new Coordinate(candidate.name(), candidate.version());
        List<RuleHit> hits = matchingRules(original);
        if (hits.isEmpty()) {
            return null;
        }
        // 同优先级冲突：最高优先级层若有多条不同规则命中，无法决断。
        RuleHit selected = selectByPriority(hits);
        if (selected == null) {
            throw new SubstitutionConflictException(
                    "原坐标 " + original.name() + ":" + original.version()
                            + " 命中同优先级的多条替代规则，策略冲突");
        }

        List<RejectedCandidate> rejected = new ArrayList<>();
        for (Coordinate alt : selected.rule().alternatives()) {
            String reject = evaluateAlternative(original, alt, chosen);
            if (reject == null) {
                commitSubstitution(original, selected, alt, rejected);
                return findArtifact(alt.name(), alt.version());
            }
            rejected.add(new RejectedCandidate(alt.name(), alt.version(), reject));
        }
        return null;
    }

    /**
     * 校验单个替代候选：原坐标与替代坐标不能相同、候选须存在且未撤回且平台可用、
     * 不能形成坐标环、不能与该原节点既有的唯一替代结果冲突。
     *
     * @return null 表示可接受；否则为拒绝原因
     */
    private String evaluateAlternative(Coordinate original, Coordinate alt,
                                       TreeMap<String, ArtifactVersion> chosen) {
        if (alt.name().equals(original.name()) && alt.version() == original.version()) {
            return "替代坐标与原坐标相同";
        }
        ArtifactVersion artifact = findArtifact(alt.name(), alt.version());
        if (artifact == null) {
            return "替代制品版本不存在或已撤回";
        }
        if (!artifact.availableOn(platform)) {
            return "替代制品在目标平台不可用或已撤回";
        }
        // 坐标环：替代链上出现已在链中的坐标。
        if (chainContains(alt, chosen)) {
            return "替代链形成坐标环";
        }
        // 同一原节点此前已被其他路径替代为不同坐标：唯一替代冲突。
        NodeResolution existing = substitutions.get(original.name());
        if (existing != null
                && (!existing.finalName().equals(alt.name())
                || existing.finalVersion() != alt.version())) {
            return "该原节点已被替代为另一坐标";
        }
        return null;
    }

    /**
     * 判断采用 alt 后是否在当前替代链中形成坐标环：alt 的名称等于任一已选中原节点，
     * 或沿“alt 自身依赖中的原坐标是否指向链上节点”形成回路。
     * 这里采用保守且完备的判定：若 alt 名称已作为原图节点出现在 chosen 中且其与原坐标同属替代链。
     */
    private boolean chainContains(Coordinate alt, TreeMap<String, ArtifactVersion> chosen) {
        // 环的直接形式：替代目标名称与当前图中原节点重名会在版本约束处体现；
        // 坐标环特指替代链 A→B→A：沿 substitutions 链检查 alt 是否为链上祖先坐标。
        // 使用当前调用链（由 candidate 原始名称向上追溯）。
        return currentChain.contains(alt);
    }

    /** 当前递归替代调用链上的坐标，用于检测坐标环。 */
    private final java.util.Deque<Coordinate> currentChain = new java.util.ArrayDeque<>();

    /**
     * 保证某节点可用；不可用且存在替代时完成替代并返回替代后的制品。
     * 用于根节点（根也可命中替代规则）。返回 null 表示无可用节点。
     */
    private ArtifactVersion ensureAvailable(ArtifactVersion node, List<RejectedCandidate> rejected) {
        if (node.availableOn(platform)) {
            return node;
        }
        currentChain.push(new Coordinate(node.name(), node.version()));
        try {
            Coordinate original = new Coordinate(node.name(), node.version());
            List<RuleHit> hits = matchingRules(original);
            if (hits.isEmpty()) {
                return null;
            }
            RuleHit selected = selectByPriority(hits);
            if (selected == null) {
                throw new SubstitutionConflictException(
                        "原坐标 " + original.name() + ":" + original.version()
                                + " 命中同优先级的多条替代规则，策略冲突");
            }
            TreeMap<String, ArtifactVersion> empty = new TreeMap<>();
            for (Coordinate alt : selected.rule().alternatives()) {
                String reject = evaluateAlternative(original, alt, empty);
                if (reject != null) {
                    rejected.add(new RejectedCandidate(alt.name(), alt.version(), reject));
                    continue;
                }
                ArtifactVersion artifact = findArtifact(alt.name(), alt.version());
                // 根替代后继续保证其多跳可用：替代坐标自身不可用则继续沿链替代。
                currentChain.push(alt);
                ArtifactVersion effective;
                try {
                    effective = ensureAvailable(artifact, rejected);
                } finally {
                    currentChain.pop();
                }
                if (effective != null) {
                    commitSubstitution(original, selected,
                            new Coordinate(effective.name(), effective.version()), rejected);
                    return effective;
                }
            }
            return null;
        } finally {
            currentChain.pop();
        }
    }

    /** 提交一个原节点的唯一替代结果与解释步骤。 */
    private void commitSubstitution(Coordinate original, RuleHit hit,
                                    Coordinate finalCoordinate,
                                    List<RejectedCandidate> rejected) {
        NodeResolution existing = substitutions.get(original.name());
        if (existing != null) {
            if (!existing.finalName().equals(finalCoordinate.name())
                    || existing.finalVersion() != finalCoordinate.version()) {
                throw new SubstitutionConflictException(
                        "原节点 " + original.name() + " 的两个路径提出不同替代结果");
            }
            return;
        }
        SubstitutionStep step = new SubstitutionStep(
                original, hit.rule().id(), hit.rule().ruleIndex(),
                hit.rule().sourcePattern(), finalCoordinate,
                List.copyOf(rejected), policyVersion);
        substitutions.put(original.name(),
                new NodeResolution(finalCoordinate.name(), finalCoordinate.version()));
        steps.add(step);
    }

    /** 找出对原坐标生效（平台一致、时刻已到、模式命中）的全部规则。 */
    private List<RuleHit> matchingRules(Coordinate coordinate) {
        List<RuleHit> hits = new ArrayList<>();
        for (SubstitutionRule rule : rules) {
            if (!rule.targetPlatform().equals(platform)) {
                continue;
            }
            if (now.isBefore(rule.effectiveAt())) {
                continue;
            }
            if (CoordinatePattern.parse(rule.sourcePattern()).matches(coordinate)) {
                hits.add(new RuleHit(rule));
            }
        }
        return hits;
    }

    /**
     * 同优先级冲突判定：若同一原坐标被多条规则命中，这些规则必须处于不同优先级层级；
     * 本模型中规则没有显式“规则优先级”字段，按题意“规则同优先级冲突”指候选并列。
     * 因此多条规则同时命中即同优先级冲突，返回 null；唯一命中返回该规则。
     */
    private RuleHit selectByPriority(List<RuleHit> hits) {
        if (hits.size() == 1) {
            return hits.get(0);
        }
        return null;
    }

    private boolean satisfiesChosen(ArtifactVersion candidate,
                                    Map<String, ArtifactVersion> chosen) {
        for (DependencyRange dep : candidate.dependencies()) {
            ArtifactVersion selected = chosen.get(dep.name());
            if (selected == null) {
                // 也可能依赖的是已替代节点的最终名称之外的原名。
                NodeResolution resolution = substitutions.get(dep.name());
                if (resolution == null) {
                    continue;
                }
                selected = chosen.get(resolution.finalName());
                if (selected == null) {
                    continue;
                }
            }
            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
                return false;
            }
        }
        return true;
    }

    /** 原名称 -> 最终替代坐标的唯一映射。 */
    private record NodeResolution(String finalName, int finalVersion) {
    }

    private record RuleHit(SubstitutionRule rule) {
    }

    /** 替代策略冲突：整体锁定必须 422。 */
    public static class SubstitutionConflictException extends RuntimeException {
        public SubstitutionConflictException(String message) {
            super(message);
        }
    }
}

