package com.example.starter.domain;

import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * 支持依赖替代的锁定解析器。
 *
 * <p>流程：先按既有区间规则选择依赖版本；仅当选中版本已撤回或在目标平台不可用时，
 * 才按当前生效策略依次尝试替代。每次替代后由外层回溯重新解析该节点的完整传递依赖，
 * 直至得到可用节点或明确失败。
 *
 * <p>替代选择对同一原坐标是确定的：唯一命中规则 + 按候选优先级取首个结构上可行的坐标，
 * 替代链可多跳。下列情况整体失败（调用方转 422）：同一原坐标被多条规则命中
 * （规则同优先级冲突）、两个路径对同一原节点得到不同替代结果、替代后版本约束不相容、
 * 替代链形成坐标环。
 */
public final class SubstitutionResolver {

    private final Map<String, List<ArtifactVersion>> all;
    private final List<SubstitutionRule> rules;
    private final String platform;
    private final Instant now;
    private final Long policyVersion;

    /** 原坐标 -> 已确定的唯一替代结果。 */
    private final TreeMap<Coordinate, Coordinate> substitutions = new TreeMap<>(
            java.util.Comparator.comparing(Coordinate::name).thenComparingInt(Coordinate::version));
    private final List<SubstitutionStep> steps = new ArrayList<>();
    /** 当前替代展开链上的坐标，用于检测坐标环。 */
    private final Deque<Coordinate> chain = new ArrayDeque<>();

    private SubstitutionResolver(RepositorySnapshot snapshot, SubstitutionPolicy policy,
                                 String platform, Instant now) {
        this.all = snapshot.artifacts();
        this.rules = policy == null ? List.of() : policy.rules();
        this.platform = platform;
        this.now = now;
        this.policyVersion = policy == null ? null : policy.policyVersion();
    }

    /**
     * 在给定快照与策略上解析锁定。
     *
     * @return 解析结果；无可行组合时返回 null（调用方转 422）
     * @throws SubstitutionConflictException 替代策略冲突，整体 422
     */
    public static ResolutionResult resolve(RepositorySnapshot snapshot,
                                           String rootName, int rootVersion,
                                           SubstitutionPolicy policy,
                                           String platform, Instant now) {
        SubstitutionResolver resolver = new SubstitutionResolver(snapshot, policy, platform, now);
        Map<String, Integer> solution = resolver.doResolve(rootName, rootVersion);
        if (solution == null) {
            return null;
        }
        return new ResolutionResult(solution, List.copyOf(resolver.steps),
                resolver.policyVersion);
    }

    private Map<String, Integer> doResolve(String rootName, int rootVersion) {
        List<ArtifactVersion> rootCandidates = all.get(rootName);
        if (rootCandidates == null) {
            throw new IllegalArgumentException("根制品不存在: " + rootName);
        }
        ArtifactVersion root = rootCandidates.stream()
                .filter(a -> a.version() == rootVersion && !a.withdrawn())
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException(
                        "根制品版本不存在或已撤回: " + rootName + ":" + rootVersion));

        TreeMap<String, ArtifactVersion> chosen = new TreeMap<>();
        ArtifactVersion effectiveRoot = root;
        if (!root.availableOn(platform)) {
            // 根坐标在目标平台不可用：同样按策略展开替代链。
            Expansion rootExpansion = expandChain(new Coordinate(rootName, rootVersion));
            if (rootExpansion == null) {
                return null;
            }
            effectiveRoot = mustFind(rootExpansion.coordinate());
        }
        chosen.put(effectiveRoot.name(), effectiveRoot);
        if (!satisfiesChosen(effectiveRoot, chosen)) {
            return null;
        }
        if (solve(chosen)) {
            TreeMap<String, Integer> result = new TreeMap<>();
            chosen.forEach((name, artifact) -> result.put(name, artifact.version()));
            return result;
        }
        return null;
    }

    /**
     * 递归回溯。待解析依赖以“原名称”聚合区间；已替代原名称的边重定向到最终坐标名称。
     */
    private boolean solve(TreeMap<String, ArtifactVersion> chosen) {
        TreeMap<String, int[]> pending = new TreeMap<>();
        for (ArtifactVersion artifact : chosen.values()) {
            for (DependencyRange dep : artifact.dependencies()) {
                String originalName = dep.name();
                String targetName = retarget(originalName);
                if (chosen.containsKey(targetName)) {
                    continue;
                }
                int[] range = pending.computeIfAbsent(originalName, k -> new int[]{1, Integer.MAX_VALUE});
                range[0] = Math.max(range[0], dep.minimumVersion());
                range[1] = Math.min(range[1], dep.maximumVersion());
            }
        }

        if (pending.isEmpty()) {
            return true;
        }

        for (Map.Entry<String, int[]> entry : pending.entrySet()) {
            String originalName = entry.getKey();
            int lo = entry.getValue()[0];
            int hi = entry.getValue()[1];
            if (lo > hi) {
                return false;
            }

            // 该原名称若已有确定替代（其他路径先到达），最终坐标是唯一强制候选。
            Coordinate forced = forcedSubstitution(originalName);
            if (forced != null) {
                if (forced.version() < lo || forced.version() > hi) {
                    throw new SubstitutionConflictException(
                            "原节点 " + originalName + " 的替代坐标版本 " + forced.version()
                                    + " 不满足区间 [" + lo + "," + hi + "]，版本约束不相容");
                }
                ArtifactVersion forcedArtifact = mustFind(forced);
                if (chosen.containsKey(forcedArtifact.name())) {
                    continue;
                }
                if (!satisfiesChosen(forcedArtifact, chosen)) {
                    throw new SubstitutionConflictException(
                            "原节点 " + originalName + " 的替代结果与既有版本约束不相容");
                }
                int mark = checkpoint();
                chosen.put(forcedArtifact.name(), forcedArtifact);
                chainPushPath(originalName, forced);
                if (solve(chosen)) {
                    return true;
                }
                chainPopPath(originalName, forced);
                chosen.remove(forcedArtifact.name());
                rollback(mark);
                return false;
            }

            List<ArtifactVersion> candidates = all.getOrDefault(originalName, List.of());
            for (ArtifactVersion candidate : candidates) {
                if (candidate.version() < lo || candidate.version() > hi) {
                    continue;
                }
                if (candidate.availableOn(platform)) {
                    if (!satisfiesChosen(candidate, chosen)) {
                        continue;
                    }
                    chosen.put(originalName, candidate);
                    if (solve(chosen)) {
                        return true;
                    }
                    chosen.remove(originalName);
                    continue;
                }

                // 选中版本撤回/平台不可用：按策略展开替代链。
                Coordinate original = new Coordinate(originalName, candidate.version());
                int mark = checkpoint();
                Expansion expansion;
                chain.push(original);
                try {
                    expansion = expandChain(original);
                } finally {
                    chain.pop();
                }
                if (expansion == null) {
                    rollback(mark);
                    continue;
                }
                Coordinate finalCoordinate = expansion.coordinate();
                if (finalCoordinate.version() < lo || finalCoordinate.version() > hi) {
                    rollback(mark);
                    throw new SubstitutionConflictException(
                            "原节点 " + originalName + " 的替代坐标版本 " + finalCoordinate.version()
                                    + " 不满足区间 [" + lo + "," + hi + "]，版本约束不相容");
                }
                ArtifactVersion replaced = mustFind(finalCoordinate);
                if (chosen.containsKey(replaced.name())) {
                    // 最终名称已由其他节点选定：必须是同一精确版本，否则冲突。
                    ArtifactVersion present = chosen.get(replaced.name());
                    if (present.version() != replaced.version()) {
                        rollback(mark);
                        throw new SubstitutionConflictException(
                                "替代最终坐标 " + replaced.name() + " 与图中已选版本冲突");
                    }
                } else if (!satisfiesChosen(replaced, chosen)) {
                    rollback(mark);
                    throw new SubstitutionConflictException(
                            "原节点 " + originalName + " 替代后与既有版本约束不相容");
                } else {
                    chosen.put(replaced.name(), replaced);
                }
                if (solve(chosen)) {
                    return true;
                }
                chosen.remove(replaced.name());
                rollback(mark);
            }
        }
        return false;
    }

    /** 沿替代映射把原名称重定向到最终坐标名称；无替代时原样返回。 */
    private String retarget(String originalName) {
        for (Map.Entry<Coordinate, Coordinate> e : substitutions.entrySet()) {
            if (e.getKey().name().equals(originalName)) {
                return e.getValue().name();
            }
        }
        return originalName;
    }

    /** 返回该原名称（任意版本）已确定的替代最终坐标；不存在返回 null。 */
    private Coordinate forcedSubstitution(String originalName) {
        for (Map.Entry<Coordinate, Coordinate> e : substitutions.entrySet()) {
            if (e.getKey().name().equals(originalName)) {
                return e.getValue();
            }
        }
        return null;
    }

    /** 强制复用既有替代路径时同步压入链坐标，供深层环检测。 */
    private void chainPushPath(String originalName, Coordinate finalCoordinate) {
        Coordinate cur = null;
        for (Coordinate key : substitutions.keySet()) {
            if (key.name().equals(originalName)) {
                cur = key;
                break;
            }
        }
        Deque<Coordinate> path = new ArrayDeque<>();
        while (cur != null) {
            path.push(cur);
            Coordinate next = substitutions.get(cur);
            if (next == null || next.equals(cur)) {
                break;
            }
            cur = findKey(next);
        }
        path.forEach(chain::push);
    }

    private void chainPopPath(String originalName, Coordinate finalCoordinate) {
        int hops = 0;
        Coordinate cur = null;
        for (Coordinate key : substitutions.keySet()) {
            if (key.name().equals(originalName)) {
                cur = key;
                break;
            }
        }
        while (cur != null) {
            hops++;
            Coordinate next = substitutions.get(cur);
            if (next == null || next.equals(cur)) {
                break;
            }
            cur = findKey(next);
        }
        for (int i = 0; i < hops; i++) {
            chain.pop();
        }
    }

    private Coordinate findKey(Coordinate value) {
        for (Map.Entry<Coordinate, Coordinate> e : substitutions.entrySet()) {
            if (e.getValue().equals(value)) {
                return e.getKey();
            }
        }
        return null;
    }

    /**
     * 对不可用原坐标展开替代链，返回链末端的可用坐标；无可行替代返回 null。
     * 每一跳记录一个解释步骤（含该跳候选拒绝原因）。展开期间的状态为试探性，
     * 调用方在外层回溯失败时通过 {@link #rollback} 撤销。
     */
    private Expansion expandChain(Coordinate original) {
        List<RuleHit> hits = matchingRules(original);
        if (hits.isEmpty()) {
            return null;
        }
        if (hits.size() > 1) {
            throw new SubstitutionConflictException(
                    "原坐标 " + original.name() + ":" + original.version()
                            + " 同时命中 " + hits.size() + " 条同优先级替代规则，规则冲突");
        }
        SubstitutionRule rule = hits.get(0).rule();
        List<RejectedCandidate> rejected = new ArrayList<>();

        for (Coordinate alt : rule.alternatives()) {
            String reason = structuralReject(original, alt);
            if (reason != null) {
                rejected.add(new RejectedCandidate(alt.name(), alt.version(), reason));
                continue;
            }
            ArtifactVersion altArtifact = mustFind(alt);
            if (altArtifact.availableOn(platform)) {
                commitHop(original, rule, alt, rejected);
                return new Expansion(alt);
            }
            // 替代坐标自身仍不可用：多跳继续替代；无规则时拒绝该候选。
            chain.push(alt);
            Expansion deeper;
            try {
                deeper = expandChain(alt);
            } finally {
                chain.pop();
            }
            if (deeper == null) {
                rejected.add(new RejectedCandidate(alt.name(), alt.version(),
                        "替代坐标在目标平台不可用且无后续可行替代"));
                continue;
            }
            commitHop(original, rule, deeper.coordinate(), rejected);
            return deeper;
        }
        return null;
    }

    /** 候选结构校验：原坐标与替代坐标不能相同；坐标须存在；不能形成坐标环。 */
    private String structuralReject(Coordinate original, Coordinate alt) {
        if (alt.name().equals(original.name()) && alt.version() == original.version()) {
            return "替代坐标与原坐标相同";
        }
        ArtifactVersion artifact = findArtifact(alt.name(), alt.version());
        if (artifact == null) {
            return "替代制品版本不存在或已撤回";
        }
        if (chain.contains(alt)) {
            return "替代链形成坐标环";
        }
        // 与同一原坐标既有的唯一替代结果不同即路径冲突。
        Coordinate existing = substitutions.get(original);
        if (existing != null && !existing.equals(alt)) {
            throw new SubstitutionConflictException(
                    "原节点 " + original.name() + ":" + original.version()
                            + " 经两个路径得到不同替代结果："
                            + existing.name() + ":" + existing.version()
                            + " 与 " + alt.name() + ":" + alt.version());
        }
        return null;
    }

    /** 提交一跳替代并冻结解释；同原坐标同结果重复到达时幂等保留首条解释。 */
    private void commitHop(Coordinate original, SubstitutionRule rule,
                           Coordinate finalCoordinate, List<RejectedCandidate> rejected) {
        Coordinate existing = substitutions.get(original);
        if (existing != null) {
            if (!existing.equals(finalCoordinate)) {
                throw new SubstitutionConflictException(
                        "原节点 " + original.name() + ":" + original.version()
                                + " 经两个路径得到不同替代结果");
            }
            return;
        }
        substitutions.put(original, finalCoordinate);
        steps.add(new SubstitutionStep(original, rule.id(), rule.ruleIndex(),
                rule.sourcePattern(), finalCoordinate, List.copyOf(rejected),
                policyVersion == null ? -1L : policyVersion));
    }

    private int checkpoint() {
        return steps.size();
    }

    /** 回溯时撤销试探性替代步骤与映射。 */
    private void rollback(int mark) {
        while (steps.size() > mark) {
            SubstitutionStep removed = steps.remove(steps.size() - 1);
            substitutions.remove(removed.original());
        }
    }

    /** 找出对原坐标生效（平台一致、时刻已到、模式命中）的全部规则。 */
    private List<RuleHit> matchingRules(Coordinate coordinate) {
        List<RuleHit> hits = new ArrayList<>();
        for (SubstitutionRule rule : rules) {
            if (!rule.targetPlatform().equals(platform)) {
                continue;
            }
            if (now.isBefore(rule.effectiveAt())) {
                continue;
            }
            if (CoordinatePattern.parse(rule.sourcePattern()).matches(coordinate)) {
                hits.add(new RuleHit(rule));
            }
        }
        return hits;
    }

    private ArtifactVersion mustFind(Coordinate coordinate) {
        ArtifactVersion artifact = findArtifact(coordinate.name(), coordinate.version());
        if (artifact == null) {
            throw new SubstitutionConflictException(
                    "替代制品版本不存在或已撤回: " + coordinate.name() + ":" + coordinate.version());
        }
        return artifact;
    }

    private ArtifactVersion findArtifact(String name, int version) {
        List<ArtifactVersion> candidates = all.get(name);
        if (candidates == null) {
            return null;
        }
        return candidates.stream()
                .filter(a -> a.version() == version && !a.withdrawn())
                .findFirst().orElse(null);
    }

    private boolean satisfiesChosen(ArtifactVersion candidate,
                                    Map<String, ArtifactVersion> chosen) {
        for (DependencyRange dep : candidate.dependencies()) {
            String targetName = retarget(dep.name());
            ArtifactVersion selected = chosen.get(targetName);
            if (selected == null) {
                continue;
            }
            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
                return false;
            }
        }
        return true;
    }

    private record Expansion(Coordinate coordinate) {
    }

    private record RuleHit(SubstitutionRule rule) {
    }

    /** 替代策略冲突：整体锁定必须 422，不生成部分锁。 */
    public static class SubstitutionConflictException extends RuntimeException {
        public SubstitutionConflictException(String message) {
            super(message);
        }
    }
}

