package com.example.starter.domain;

import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * 支持依赖替代的锁定解析器。
 *
 * <p>两阶段：
 * <ol>
 *   <li>{@link #expandChain} 对不可用原坐标做确定性的替代链展开——唯一命中规则，
 *       候选按优先级取首个结构可行（存在、未撤回、平台可用、不同于原坐标、链不成环）坐标，
 *       替代坐标自身不可用则多跳继续。结果按原坐标记忆，整图一致。</li>
 *   <li>{@link #solve} 在区间回溯求解中，仅当选中版本撤回或平台不可用时才替代；
 *       替代后重新解析最终坐标的完整传递依赖（外层递归自然完成），
 *       版本约束不相容、最终坐标撞版本等导致无解时整体失败（调用方转 422）。</li>
 * </ol>
 *
 * <p>冲突（直接抛 {@link SubstitutionConflictException}，整体 422）：
 * 同一原坐标命中多条规则（同优先级冲突）；同一原名称在一条求解路径上得到不同替代结果；
 * 两个原节点的替代最终坐标同名异版；替代链形成坐标环。
 */
public final class SubstitutionResolver {

    private final Map<String, List<ArtifactVersion>> all;
    private final List<SubstitutionRule> rules;
    private final String platform;
    private final Instant now;
    private final Long policyVersion;

    /** 原坐标 -> 替代链展开结果（确定性，结构校验后记忆，回溯不撤销）。 */
    private final Map<Coordinate, Expansion> expansions = new HashMap<>();
    /** 替代链展开中正在访问的原坐标，检测坐标环。 */
    private final Deque<Coordinate> activeChain = new ArrayDeque<>();
    private final List<SubstitutionStep> steps = new ArrayList<>();

    private SubstitutionResolver(RepositorySnapshot snapshot, SubstitutionPolicy policy,
                                 String platform, Instant now) {
        this.all = snapshot.artifacts();
        this.rules = policy == null ? List.of() : policy.rules();
        this.platform = platform;
        this.now = now;
        this.policyVersion = policy == null ? null : policy.policyVersion();
    }

    /**
     * 在给定快照与策略上解析锁定。
     *
     * @return 解析结果；无可行组合时返回 null（调用方转 422）
     * @throws SubstitutionConflictException 替代策略冲突，整体 422
     */
    public static ResolutionResult resolve(RepositorySnapshot snapshot,
                                           String rootName, int rootVersion,
                                           SubstitutionPolicy policy,
                                           String platform, Instant now) {
        SubstitutionResolver resolver = new SubstitutionResolver(snapshot, policy, platform, now);
        Map<String, Integer> solution = resolver.doResolve(rootName, rootVersion);
        if (solution == null) {
            return null;
        }
        // 仅保留最终解所在路径使用到的替代步骤（按提交顺序天然稳定）。
        return new ResolutionResult(solution, List.copyOf(resolver.steps), resolver.policyVersion);
    }

    private Map<String, Integer> doResolve(String rootName, int rootVersion) {
        List<ArtifactVersion> rootCandidates = all.get(rootName);
        if (rootCandidates == null) {
            throw new IllegalArgumentException("根制品不存在: " + rootName);
        }
        ArtifactVersion root = rootCandidates.stream()
                .filter(a -> a.version() == rootVersion && !a.withdrawn())
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException(
                        "根制品版本不存在或已撤回: " + rootName + ":" + rootVersion));

        TreeMap<String, ArtifactVersion> chosen = new TreeMap<>();
        // 求解路径状态：原名称 -> 最终坐标；以及已选最终名称 -> 原名称，随回溯撤销。
        Map<String, Coordinate> substituteByName = new HashMap<>();
        Map<String, String> finalNameToOriginal = new HashMap<>();

        ArtifactVersion rootToUse = root;
        if (!root.availableOn(platform)) {
            Coordinate rootCoordinate = new Coordinate(rootName, rootVersion);
            Expansion expansion = requireExpansion(rootCoordinate);
            rootToUse = mustFind(expansion.finalCoordinate());
            substituteByName.put(rootName, expansion.finalCoordinate());
            finalNameToOriginal.put(rootToUse.name(), rootName);
        }
        chosen.put(rootToUse.name(), rootToUse);
        if (!satisfiesChosen(rootToUse, chosen, substituteByName)) {
            return null;
        }
        if (solve(chosen, substituteByName, finalNameToOriginal)) {
            TreeMap<String, Integer> result = new TreeMap<>();
            chosen.forEach((name, artifact) -> result.put(name, artifact.version()));
            return result;
        }
        return null;
    }

    /**
     * 递归回溯。对每个未解析依赖名称聚合全部已选制品的区间（取交集），
     * 候选版本从高到低；候选不可用时按策略替代，替代结果随分支记忆/回滚。
     */
    private boolean solve(TreeMap<String, ArtifactVersion> chosen,
                          Map<String, Coordinate> substituteByName,
                          Map<String, String> finalNameToOriginal) {
        String next = null;
        int lo = Integer.MAX_VALUE;
        int hi = Integer.MIN_VALUE;
        for (ArtifactVersion artifact : chosen.values()) {
            for (DependencyRange dep : artifact.dependencies()) {
                String targetName = retarget(dep.name(), substituteByName);
                if (chosen.containsKey(targetName)) {
                    continue;
                }
                String originalName = dep.name();
                if (next == null || originalName.compareTo(next) < 0) {
                    next = originalName;
                    lo = dep.minimumVersion();
                    hi = dep.maximumVersion();
                } else if (originalName.equals(next)) {
                    lo = Math.max(lo, dep.minimumVersion());
                    hi = Math.min(hi, dep.maximumVersion());
                }
            }
        }

        if (next == null) {
            return true;
        }
        if (lo > hi) {
            return false;
        }

        List<ArtifactVersion> candidates = all.getOrDefault(next, List.of());
        for (ArtifactVersion candidate : candidates) {
            if (candidate.version() < lo || candidate.version() > hi) {
                continue;
            }
            if (candidate.availableOn(platform)) {
                if (chosen.containsKey(next) || !satisfiesChosen(candidate, chosen, substituteByName)) {
                    continue;
                }
                chosen.put(next, candidate);
                if (solve(chosen, substituteByName, finalNameToOriginal)) {
                    return true;
                }
                chosen.remove(next);
                continue;
            }

            // 选中版本撤回/平台不可用：确定性展开替代链。
            Coordinate original = new Coordinate(next, candidate.version());
            Expansion expansion;
            try {
                expansion = requireExpansion(original);
            } catch (SubstitutionConflictException hard) {
                // 坐标环、同优先级冲突等硬性策略冲突：不可通过换版本回避，整体 422。
                throw hard;
            }
            Coordinate finalCoordinate = expansion.finalCoordinate();

            // 原节点在本路径上只能有一个替代结果。
            Coordinate existingByName = substituteByName.get(next);
            if (existingByName != null && !existingByName.equals(finalCoordinate)) {
                throw new SubstitutionConflictException(
                        "原节点 " + next + " 经两个路径得到不同替代结果："
                                + existingByName.name() + ":" + existingByName.version()
                                + " 与 " + finalCoordinate.name() + ":" + finalCoordinate.version());
            }

            // 替代后版本约束不相容：区间必须包含最终坐标版本。
            if (finalCoordinate.version() < lo || finalCoordinate.version() > hi) {
                // 仍可尝试该名称的更低版本候选；仅当全部候选失败时由外层返回无解。
                continue;
            }
            ArtifactVersion replaced = mustFind(finalCoordinate);

            // 最终名称已在图中：必须同一精确版本，否则两个替代结果相互冲突。
            ArtifactVersion present = chosen.get(replaced.name());
            if (present != null) {
                if (present.version() != replaced.version()) {
                    throw new SubstitutionConflictException(
                            "原节点 " + next + " 的替代最终坐标 " + replaced.name() + ":"
                                    + replaced.version() + " 与图中已选版本 "
                                    + present.version() + " 冲突");
                }
            } else if (!satisfiesChosen(replaced, chosen, substituteByName)) {
                // 替代坐标声明的依赖与已选版本不相容：尝试下一原版本候选。
                continue;
            } else {
                chosen.put(replaced.name(), replaced);
            }

            substituteByName.put(next, finalCoordinate);
            String previousOwner = finalNameToOriginal.put(replaced.name(), next);
            boolean ok = solve(chosen, substituteByName, finalNameToOriginal);
            if (ok) {
                return true;
            }
            finalNameToOriginal.remove(replaced.name());
            if (previousOwner != null) {
                finalNameToOriginal.put(replaced.name(), previousOwner);
            }
            substituteByName.remove(next, finalCoordinate);
            if (present == null) {
                chosen.remove(replaced.name());
            }
        }
        return false;
    }

    /** 取原坐标的替代链展开结果，不存在可行替代时抛无解（由上层视作该候选失败）。 */
    private Expansion requireExpansion(Coordinate original) {
        Expansion cached = expansions.get(original);
        if (cached != null) {
            if (cached.finalCoordinate() == null) {
                return cached;
            }
            return cached;
        }
        Expansion expansion = expandChain(original, new ArrayList<>());
        expansions.put(original, expansion);
        if (expansion.finalCoordinate() == null) {
            return expansion;
        }
        return expansion;
    }

    /**
     * 对不可用原坐标展开替代链。
     *
     * @param rejectedAccum 本跳累积的候选拒绝原因（多跳时透传首跳）
     * @return 末端可用坐标；全部候选不可行时 finalCoordinate 为 null
     */
    private Expansion expandChain(Coordinate original, List<RejectedCandidate> rejectedAccum) {
        if (activeChain.contains(original)) {
            throw new SubstitutionConflictException(
                    "替代链形成坐标环：" + describeChain(original));
        }
        activeChain.push(original);
        try {
            List<RuleHit> hits = matchingRules(original);
            if (hits.isEmpty()) {
                return Expansion.unavailable();
            }
            if (hits.size() > 1) {
                throw new SubstitutionConflictException(
                        "原坐标 " + original.name() + ":" + original.version()
                                + " 同时命中 " + hits.size() + " 条同优先级替代规则，规则冲突");
            }
            SubstitutionRule rule = hits.get(0).rule();

            List<RejectedCandidate> rejected = rejectedAccum;
            for (Coordinate alt : rule.alternatives()) {
                String reason = structuralReject(original, alt);
                if (reason != null) {
                    rejected.add(new RejectedCandidate(alt.name(), alt.version(), reason));
                    continue;
                }
                ArtifactVersion altArtifact = mustFind(alt);
                if (altArtifact.availableOn(platform)) {
                    commitHop(original, rule, alt, rejected);
                    return Expansion.of(alt);
                }
                // 替代坐标自身仍不可用：多跳继续替代。
                List<RejectedCandidate> nextHopRejected = new ArrayList<>();
                Expansion deeper = expandChain(alt, nextHopRejected);
                if (deeper.finalCoordinate() == null) {
                    rejected.add(new RejectedCandidate(alt.name(), alt.version(),
                            "替代坐标在目标平台不可用且无后续可行替代"));
                    continue;
                }
                commitHop(original, rule, deeper.finalCoordinate(), rejected);
                return deeper;
            }
            return Expansion.unavailable();
        } finally {
            activeChain.pop();
        }
    }

    /** 候选结构校验：原坐标与替代坐标不能相同；坐标须存在且未撤回；不能形成坐标环。 */
    private String structuralReject(Coordinate original, Coordinate alt) {
        if (alt.name().equals(original.name()) && alt.version() == original.version()) {
            return "替代坐标与原坐标相同";
        }
        ArtifactVersion artifact = findArtifact(alt.name(), alt.version());
        if (artifact == null) {
            return "替代制品版本不存在或已撤回";
        }
        if (activeChain.contains(alt)) {
            return "替代链形成坐标环";
        }
        return null;
    }

    /** 提交一跳替代解释；同一原坐标重复到达时结果必须一致，否则硬性冲突。 */
    private void commitHop(Coordinate original, SubstitutionRule rule,
                           Coordinate finalCoordinate, List<RejectedCandidate> rejected) {
        Expansion prior = expansions.get(original);
        if (prior != null && prior.finalCoordinate() != null
                && !prior.finalCoordinate().equals(finalCoordinate)) {
            throw new SubstitutionConflictException(
                    "原坐标 " + original.name() + ":" + original.version()
                            + " 得到不一致的替代结果");
        }
        steps.add(new SubstitutionStep(original, rule.id(), rule.ruleIndex(),
                rule.sourcePattern(), finalCoordinate, List.copyOf(rejected),
                policyVersion == null ? -1L : policyVersion));
    }

    /** 找出对原坐标生效（平台一致、时刻已到、模式命中）的全部规则。 */
    private List<RuleHit> matchingRules(Coordinate coordinate) {
        List<RuleHit> hits = new ArrayList<>();
        for (SubstitutionRule rule : rules) {
            if (!rule.targetPlatform().equals(platform)) {
                continue;
            }
            if (now.isBefore(rule.effectiveAt())) {
                continue;
            }
            if (CoordinatePattern.parse(rule.sourcePattern()).matches(coordinate)) {
                hits.add(new RuleHit(rule));
            }
        }
        return hits;
    }

    /** 依赖名称若在本路径已替代，则重定向到最终名称。 */
    private String retarget(String originalName, Map<String, Coordinate> substituteByName) {
        Coordinate mapped = substituteByName.get(originalName);
        return mapped == null ? originalName : mapped.name();
    }

    private ArtifactVersion mustFind(Coordinate coordinate) {
        ArtifactVersion artifact = findArtifact(coordinate.name(), coordinate.version());
        if (artifact == null) {
            throw new SubstitutionConflictException(
                    "替代制品版本不存在或已撤回: " + coordinate.name() + ":" + coordinate.version());
        }
        return artifact;
    }

    private ArtifactVersion findArtifact(String name, int version) {
        List<ArtifactVersion> candidates = all.get(name);
        if (candidates == null) {
            return null;
        }
        return candidates.stream()
                .filter(a -> a.version() == version && !a.withdrawn())
                .findFirst().orElse(null);
    }

    private boolean satisfiesChosen(ArtifactVersion candidate,
                                    Map<String, ArtifactVersion> chosen,
                                    Map<String, Coordinate> substituteByName) {
        for (DependencyRange dep : candidate.dependencies()) {
            String targetName = retarget(dep.name(), substituteByName);
            ArtifactVersion selected = chosen.get(targetName);
            if (selected == null) {
                continue;
            }
            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
                return false;
            }
        }
        return true;
    }

    private String describeChain(Coordinate closing) {
        StringBuilder sb = new StringBuilder(closing.name()).append(':').append(closing.version());
        for (Coordinate coordinate : activeChain) {
            sb.append(" <- ").append(coordinate.name()).append(':').append(coordinate.version());
        }
        return sb.toString();
    }

    /** 替代链展开结果：finalCoordinate 为 null 表示无可行替代。 */
    private record Expansion(Coordinate finalCoordinate) {
        static Expansion of(Coordinate coordinate) {
            return new Expansion(coordinate);
        }

        static Expansion unavailable() {
            return new Expansion(null);
        }
    }

    private record RuleHit(SubstitutionRule rule) {
    }

    /** 替代策略冲突：整体锁定必须 422，不生成部分锁。 */
    public static class SubstitutionConflictException extends RuntimeException {
        public SubstitutionConflictException(String message) {
            super(message);
        }
    }
}

