            }
            ArtifactVersion replaced = mustFind(finalCoordinate);

            // 最终名称已在图中：必须同一精确版本，否则两个替代结果相互冲突。
            ArtifactVersion present = chosen.get(replaced.name());
            if (present != null) {
                if (present.version() != replaced.version()) {
                    throw new SubstitutionConflictException(
                            "原节点 " + next + " 的替代最终坐标 " + replaced.name() + ":"
                                    + replaced.version() + " 与图中已选版本 "
                                    + present.version() + " 冲突");
                }
            } else if (!satisfiesChosen(replaced, chosen, substituteByName)) {
                // 替代坐标声明的依赖与已选版本不相容：尝试下一原版本候选。
                continue;
            } else {
                chosen.put(replaced.name(), replaced);
            }

            substituteByName.put(next, finalCoordinate);
            String previousOwner = finalNameToOriginal.put(replaced.name(), next);
            boolean ok = solve(chosen, substituteByName, finalNameToOriginal);
            if (ok) {
                return true;
            }
            finalNameToOriginal.remove(replaced.name());
            if (previousOwner != null) {
                finalNameToOriginal.put(replaced.name(), previousOwner);
            }
            substituteByName.remove(next, finalCoordinate);
            if (present == null) {
                chosen.remove(replaced.name());
            }
        }
        return false;
    }

    /** 取原坐标的替代链展开结果，不存在可行替代时抛无解（由上层视作该候选失败）。 */
    private Expansion requireExpansion(Coordinate original) {
        Expansion cached = expansions.get(original);
        if (cached != null) {
            if (cached.finalCoordinate() == null) {
                return cached;
            }
            return cached;
        }
        Expansion expansion = expandChain(original, new ArrayList<>());
        expansions.put(original, expansion);
        if (expansion.finalCoordinate() == null) {
            return expansion;
        }
        return expansion;
    }

    /**
     * 对不可用原坐标展开替代链。
     *
     * @param rejectedAccum 本跳累积的候选拒绝原因（多跳时透传首跳）
     * @return 末端可用坐标；全部候选不可行时 finalCoordinate 为 null
     */
    private Expansion expandChain(Coordinate original, List<RejectedCandidate> rejectedAccum) {
        if (activeChain.contains(original)) {
            throw new SubstitutionConflictException(
                    "替代链形成坐标环：" + describeChain(original));
        }
        activeChain.push(original);
        try {
            List<RuleHit> hits = matchingRules(original);
            if (hits.isEmpty()) {
                return Expansion.unavailable();
            }
            if (hits.size() > 1) {
                throw new SubstitutionConflictException(
                        "原坐标 " + original.name() + ":" + original.version()
                                + " 同时命中 " + hits.size() + " 条同优先级替代规则，规则冲突");
            }
            SubstitutionRule rule = hits.get(0).rule();

            List<RejectedCandidate> rejected = rejectedAccum;
            for (Coordinate alt : rule.alternatives()) {
                String reason = structuralReject(original, alt);
                if (reason != null) {
                    rejected.add(new RejectedCandidate(alt.name(), alt.version(), reason));
                    continue;
                }
                ArtifactVersion altArtifact = mustFind(alt);
                if (altArtifact.availableOn(platform)) {
                    commitHop(original, rule, alt, rejected);
                    return Expansion.of(alt);
                }
                // 替代坐标自身仍不可用：多跳继续替代。
                List<RejectedCandidate> nextHopRejected = new ArrayList<>();
                Expansion deeper = expandChain(alt, nextHopRejected);
                if (deeper.finalCoordinate() == null) {
                    rejected.add(new RejectedCandidate(alt.name(), alt.version(),
                            "替代坐标在目标平台不可用且无后续可行替代"));
                    continue;
                }
                commitHop(original, rule, deeper.finalCoordinate(), rejected);
                return deeper;
            }
            return Expansion.unavailable();
        } finally {
            activeChain.pop();
        }
    }

    /** 候选结构校验：原坐标与替代坐标不能相同；坐标须存在且未撤回；不能形成坐标环。 */
    private String structuralReject(Coordinate original, Coordinate alt) {
        if (alt.name().equals(original.name()) && alt.version() == original.version()) {
            return "替代坐标与原坐标相同";
        }
        ArtifactVersion artifact = findArtifact(alt.name(), alt.version());
        if (artifact == null) {
            return "替代制品版本不存在或已撤回";
        }
        if (activeChain.contains(alt)) {
            return "替代链形成坐标环";
        }
        return null;
    }

    /** 提交一跳替代解释；同一原坐标重复到达时结果必须一致，否则硬性冲突。 */
    private void commitHop(Coordinate original, SubstitutionRule rule,
                           Coordinate finalCoordinate, List<RejectedCandidate> rejected) {
        Expansion prior = expansions.get(original);
        if (prior != null && prior.finalCoordinate() != null
                && !prior.finalCoordinate().equals(finalCoordinate)) {
            throw new SubstitutionConflictException(
                    "原坐标 " + original.name() + ":" + original.version()
                            + " 得到不一致的替代结果");
        }
        steps.add(new SubstitutionStep(original, rule.id(), rule.ruleIndex(),
                rule.sourcePattern(), finalCoordinate, List.copyOf(rejected),
                policyVersion == null ? -1L : policyVersion));
    }

    /** 找出对原坐标生效（平台一致、时刻已到、模式命中）的全部规则。 */
    private List<RuleHit> matchingRules(Coordinate coordinate) {
        List<RuleHit> hits = new ArrayList<>();
        for (SubstitutionRule rule : rules) {
            if (!rule.targetPlatform().equals(platform)) {
                continue;
            }
            if (now.isBefore(rule.effectiveAt())) {
                continue;
            }
            if (CoordinatePattern.parse(rule.sourcePattern()).matches(coordinate)) {
                hits.add(new RuleHit(rule));
            }
        }
        return hits;
    }

    /** 依赖名称若在本路径已替代，则重定向到最终名称。 */
    private String retarget(String originalName, Map<String, Coordinate> substituteByName) {
        Coordinate mapped = substituteByName.get(originalName);
        return mapped == null ? originalName : mapped.name();
    }

    private ArtifactVersion mustFind(Coordinate coordinate) {
        ArtifactVersion artifact = findArtifact(coordinate.name(), coordinate.version());
        if (artifact == null) {
            throw new SubstitutionConflictException(
                    "替代制品版本不存在或已撤回: " + coordinate.name() + ":" + coordinate.version());
        }
        return artifact;
    }

    private ArtifactVersion findArtifact(String name, int version) {
        List<ArtifactVersion> candidates = all.get(name);
        if (candidates == null) {
            return null;
        }
        return candidates.stream()
                .filter(a -> a.version() == version && !a.withdrawn())
                .findFirst().orElse(null);
    }

    private boolean satisfiesChosen(ArtifactVersion candidate,
                                    Map<String, ArtifactVersion> chosen,
                                    Map<String, Coordinate> substituteByName) {
        for (DependencyRange dep : candidate.dependencies()) {
            String targetName = retarget(dep.name(), substituteByName);
            ArtifactVersion selected = chosen.get(targetName);
            if (selected == null) {
                continue;
            }
            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
                return false;
            }
        }
        return true;
    }

    private String describeChain(Coordinate closing) {
        StringBuilder sb = new StringBuilder(closing.name()).append(':').append(closing.version());
        for (Coordinate coordinate : activeChain) {
            sb.append(" <- ").append(coordinate.name()).append(':').append(coordinate.version());
        }
        return sb.toString();
    }

    /** 替代链展开结果：finalCoordinate 为 null 表示无可行替代。 */
    private record Expansion(Coordinate finalCoordinate) {
        static Expansion of(Coordinate coordinate) {
            return new Expansion(coordinate);
        }

        static Expansion unavailable() {
            return new Expansion(null);
        }
    }

    private record RuleHit(SubstitutionRule rule) {
    }

    /** 替代策略冲突：整体锁定必须 422，不生成部分锁。 */
    public static class SubstitutionConflictException extends RuntimeException {
        public SubstitutionConflictException(String message) {
            super(message);
        }
    }
}

